"""
Generate Eilmer Lua from a Document.

geometry.lua runs under both
  lmr prep-grids -j geometry.lua     (registerFluidGrid exists: register blocks, connect them)
  lmr custom-script -j geometry.lua  (it does not: write preview/blk-NNNN.vtk for the GUI)
Generation is one-way and deterministic; the Document is the source of truth.
"""
import re

from ..model.document import FACES

PREVIEW_DIR = "preview"

HEADER = """\
-- geometry.lua
-- Generated by eilmer-mesher. Edit the .emesh.json project, not this file.
--   lmr prep-grids -j geometry.lua      registers the grids for a simulation
--   lmr custom-script -j geometry.lua   writes {preview}/blk-NNNN.vtk for the GUI
if config then config.dimensions = 2 end
"""

# Jacobi Laplace smoothing as in tutes/wk7/wk7_submission.py smooth_grid():
# interior vertices move to the average of their four neighbours, boundary
# vertices stay fixed so faces shared between blocks remain matched.
LAPLACE_HELPER = """\
function laplaceSmooth(grid, nsweeps, tol)
   local niv, njv = grid:get_niv(), grid:get_njv()
   local xo, yo, xn, yn = {}, {}, {}, {}
   for i = 0, niv-1 do
      xo[i], yo[i], xn[i], yn[i] = {}, {}, {}, {}
      for j = 0, njv-1 do
         local v = grid:get_vtx(i, j)
         xo[i][j], yo[i][j], xn[i][j], yn[i][j] = v.x, v.y, v.x, v.y
      end
   end
   for n = 1, nsweeps do
      local maxChange = 0.0
      for i = 1, niv-2 do
         for j = 1, njv-2 do
            local x = 0.25*(xo[i+1][j] + xo[i-1][j] + xo[i][j+1] + xo[i][j-1])
            local y = 0.25*(yo[i+1][j] + yo[i-1][j] + yo[i][j+1] + yo[i][j-1])
            maxChange = math.max(maxChange, math.abs(x - xo[i][j]), math.abs(y - yo[i][j]))
            xn[i][j], yn[i][j] = x, y
         end
      end
      xo, xn = xn, xo
      yo, yn = yn, yo
      if maxChange < tol then break end
   end
   for i = 1, niv-2 do
      for j = 1, njv-2 do
         grid:set_vtx(i, j, Vector3:new{x=xo[i][j], y=yo[i][j]})
      end
   end
end
"""

FOOTER = """\
if registerFluidGrid then
   -- lmr prep-grids
   for _, b in ipairs(blocks) do
      registerFluidGrid{grid=b.grid, tag=b.tag, fsTag=b.fsTag, bcTags=b.bcTags}
   end
   identifyGridConnections()
else
   -- lmr custom-script: preview output for the GUI
   os.execute("mkdir -p {preview}")
   for i, b in ipairs(blocks) do
      b.grid:write_to_vtk_file(string.format("{preview}/blk-%04d.vtk", i-1))
   end
end
"""


def _num(v):
    return repr(float(v))


def _lua_value(v):
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, (int, float)):
        return repr(v)
    return '"' + str(v).replace('"', '\\"') + '"'


def _ident(s):
    return re.sub(r"\W", "_", s)


class _PointTable:
    """Deduplicates points so shared corners become one named Vector3."""

    def __init__(self):
        self.names = {}
        self.lines = []

    def name_of(self, p):
        key = (round(p[0], 12), round(p[1], 12))
        if key not in self.names:
            name = f"p{len(self.names):03d}"
            self.names[key] = name
            self.lines.append(f"{name} = Vector3:new{{x={_num(p[0])}, y={_num(p[1])}}}")
        return self.names[key]


def _face_expr(doc, refs):
    parts = []
    for r in refs:
        name = "path_" + _ident(r.id)
        parts.append(f"ReversedPath:new{{underlying_path={name}}}" if r.reversed else name)
    if len(parts) == 1:
        return parts[0]
    return "Polyline:new{segments={" + ", ".join(parts) + "}}"


def _cluster_expr(spec):
    args = ", ".join(f"{k}={_lua_value(v)}" for k, v in spec.items() if k != "type")
    return f"{spec['type']}:new{{{args}}}"


def generate_geometry_lua(doc):
    for b in doc.blocks:
        doc.validate_block(b)

    used = []
    for b in doc.blocks:
        for f in FACES:
            for r in b.sides[f]:
                if r.id not in used:
                    used.append(r.id)

    points = _PointTable()
    path_lines = []
    for cid in used:
        c = doc.curves[cid]
        path_lines.append(f"path_{_ident(cid)} = {c.lua_expr(points.name_of)}")

    out = [HEADER.replace("{preview}", PREVIEW_DIR)]
    if any(b.smoothing for b in doc.blocks):
        out.append(LAPLACE_HELPER)
    out.append("-- points")
    out.extend(points.lines)
    out.append("\n-- paths")
    out.extend(path_lines)
    out.append("\n-- blocks")
    out.append("blocks = {}")
    for b in doc.blocks:
        out.append(_block_lua(doc, b))
    out.append(FOOTER.replace("{preview}", PREVIEW_DIR))
    return "\n".join(out)


def _block_lua(doc, b):
    bid = _ident(b.id)
    faces = ", ".join(f"{f}={_face_expr(doc, b.sides[f])}" for f in FACES)
    if b.patch == "CoonsPatch":
        surf = f"CoonsPatch:new{{{faces}}}"
    elif b.patch == "AOPatch":
        nx = b.patch_opts.get("nx", 10)
        ny = b.patch_opts.get("ny", 10)
        surf = f"AOPatch:new{{{faces}, nx={nx}, ny={ny}}}"
    else:
        raise ValueError(f"block {b.id}: unsupported patch type {b.patch}")

    grid_args = f"psurface=surf_{bid}, niv={b.niv}, njv={b.njv}"
    if b.cluster:
        cf = ", ".join(f"{f}={_cluster_expr(b.cluster[f])}" for f in FACES if f in b.cluster)
        grid_args += f", cfList={{{cf}}}"
    grid_args += f', label="{b.id}"'

    bc = {f: doc.face_bc_tag(b, f) for f in FACES}
    bc_tags = ", ".join(f'{f}="{t}"' for f, t in bc.items() if t)

    lines = [f"-- block {b.id}",
             f"surf_{bid} = {surf}",
             f"grid_{bid} = StructuredGrid:new{{{grid_args}}}"]
    if b.smoothing:
        lines.append(f"laplaceSmooth(grid_{bid}, {int(b.smoothing['nsweeps'])}, "
                     f"{_num(b.smoothing.get('tol', 0.0))})")
    lines.append(f'blocks[#blocks+1] = {{grid=grid_{bid}, tag="{b.id}", fsTag="{b.fs_tag}", '
                 f"bcTags={{{bc_tags}}}}}")
    return "\n".join(lines) + "\n"


def generate_bcs_lua(doc):
    """bcDict stub mapping each tag used in the document to its chosen BC class."""
    tags = sorted({doc.face_bc_tag(b, f) for b in doc.blocks for f in FACES} - {""})
    lines = ["-- bcs.lua",
             "-- Generated by eilmer-mesher. Paste into your job script (after defining flow states)",
             "-- and pass to makeFluidBlocks(bcDict, flowDict).",
             "-- Untagged faces default to WallBC_WithSlip.",
             "bcDict = {"]
    for t in tags:
        spec = doc.bcs.get(t, {"class": "WallBC_WithSlip", "args": ""})
        lines.append(f"   {t} = {spec['class']}:new{{{spec.get('args', '')}}},")
    lines.append("}")
    return "\n".join(lines) + "\n"
